//! 🔗️ Clones genuine original shared issuances through separately funded alias and projection turns.
use super::{RetainedClone,RetainedCloneBinding,RetainedCloneClose,RetainedCloneCursor,RetainedCloneGrant,RetainedCloneRef,RetainedCloneStep};
use crate::{RetainedWorkOutcome,RetirementDemand,ValueError,ValueRefusalKind,retirement::{RetireOwned,RetirementCursor,RetirementStep},shared_issuance::SealedShared};
use std::mem::{ManuallyDrop,size_of};

struct State<T:Send+Sync+'static>{output:Option<SealedShared<T>>,source:Option<RetainedCloneBinding>,close:RetainedCloneClose,closing:bool,spent:bool,admitted:bool,close_route:Option<(crate::OriginalEffectInvocationIdentity,u8,usize)>}
pub struct SharedCloneCursor<T:Send+Sync+'static>{state:ManuallyDrop<State<T>>}
impl<T:Send+Sync+'static> Default for SharedCloneCursor<T>{fn default()->Self{Self{state:ManuallyDrop::new(State{output:None,source:None,close:Default::default(),closing:false,spent:false,admitted:false,close_route:None})}}}
impl<T:Send+Sync+'static> RetainedClone for SealedShared<T>{type Cursor=SharedCloneCursor<T>;fn retained_clone_cursor()->Self::Cursor{Default::default()}}
impl<T:Send+Sync+'static> RetainedCloneCursor<SealedShared<T>> for SharedCloneCursor<T>{
 fn requires_original_birth(&self)->bool{if !self.state.close.is_empty(){self.state.close.requires_original_birth()}else if self.state.output.is_some(){false}else{RetainedCloneBinding::requires_original_birth(&self.state.source)}}
 fn close_original_birth_step(&mut self,original:&mut crate::OriginalRetirementCloseLoan<'_>,grant:RetainedCloneGrant)->crate::OriginalRetirementPoll{if !self.state.close.is_empty(){self.state.close.step_original_birth(original,grant)}else if self.state.output.is_some(){crate::RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Err(ValueError::invariant("original Birth is not the selected cursor frontier").into()),work:0})}else{RetainedCloneBinding::close_original_birth_step(&mut self.state.source,original,grant)}}
 fn requires_original_control(&self)->bool{if !self.state.close.is_empty(){self.state.close.requires_original_control()}else if self.state.output.is_some(){false}else{RetainedCloneBinding::requires_original_control(&self.state.source)}}
 fn close_into<'reply>(&mut self,body:usize,effect:&mut crate::RetainedAllocationEffect<'_>,reply:crate::retained_clone::OriginalEffectReply<'reply,RetainedCloneStep,crate::OriginalRetirementFailure>)->Result<crate::retained_clone::OriginalEffectReplyComplete<'reply,RetainedCloneStep,crate::OriginalRetirementFailure>,ValueError>{if !self.state.closing{return Err(ValueError::invariant("cursor must begin close"))}if self.requires_original_birth()||self.requires_original_control(){return Err(ValueError::invariant("cursor requires selected original close"))}if !self.state.close.is_empty(){let invocation=effect.invocation().ok_or_else(||ValueError::invariant("cursor close lacks its original invocation"))?;if invocation.mode()!=crate::OriginalEffectCallbackMode::Receive{return Err(ValueError::invariant("cursor close is not its original receive invocation"))}if self.state.close_route.is_some(){return Err(ValueError::invariant("cursor has an unresolved original close invocation"))}let key=(invocation.identity(),1,body);let state=&mut *self.state;let mut scope=reply.progress().scope(&mut state.close_route,key)?;let done=state.close.step_into(body,effect,scope.borrow()?)?;drop(done);return Ok(scope.forwarded())}if self.state.output.is_some(){let state=&mut *self.state;let turn=state.close.begin_granted(&mut state.output,effect);return Ok(reply.complete(turn.result.map(|step|step.unwrap_or(RetainedCloneStep::Progress(Default::default()))).map_err(Into::into)))} let invocation=effect.invocation().ok_or_else(||ValueError::invariant("cursor binding close lacks its original invocation"))?;if invocation.mode()!=crate::OriginalEffectCallbackMode::Receive{return Err(ValueError::invariant("cursor close is not its original receive invocation"))}if self.state.close_route.is_some(){return Err(ValueError::invariant("cursor has an unresolved original close invocation"))}let key=(invocation.identity(),2,body);let state=&mut *self.state;let mut scope=reply.progress().scope(&mut state.close_route,key)?;let done=RetainedCloneBinding::close_into(&mut state.source,body,effect,scope.borrow()?)?;drop(done);Ok(scope.forwarded())}
 fn recover_close_into<'reply>(&mut self,body:usize,effect:&mut crate::RetainedAllocationEffect<'_>,reply:crate::retained_clone::OriginalEffectReply<'reply,RetainedCloneStep,crate::OriginalRetirementFailure>)->Result<crate::retained_clone::OriginalEffectReplyComplete<'reply,RetainedCloneStep,crate::OriginalRetirementFailure>,ValueError>{let (identity,route,selected_body)=self.state.close_route.ok_or_else(||ValueError::invariant("cursor has no original close invocation"))?;let invocation=effect.invocation().ok_or_else(||ValueError::invariant("cursor close recovery lacks its original invocation"))?;if selected_body!=body||invocation.identity()!=identity||invocation.mode()!=crate::OriginalEffectCallbackMode::Recover{return Err(ValueError::invariant("cursor close recovery changed invocation"))}let state=&mut *self.state;let mut scope=reply.progress().scope(&mut state.close_route,(identity,route,selected_body))?;let child=scope.borrow()?;let done=match route{1=>state.close.recover_step_into(body,effect,child),2=>RetainedCloneBinding::recover_close_into(&mut state.source,body,effect,child),_=>Err(ValueError::invariant("cursor close route changed"))}?;drop(done);Ok(scope.forwarded())}
 fn close_original_into<'reply>(&mut self,original:&mut crate::OriginalRetirementCloseLoan<'_>,body:usize,effect:&mut crate::RetainedAllocationEffect<'_>,reply:crate::retained_clone::OriginalEffectReply<'reply,RetainedCloneStep,crate::OriginalRetirementFailure>)->Result<crate::retained_clone::OriginalEffectReplyComplete<'reply,RetainedCloneStep,crate::OriginalRetirementFailure>,ValueError>{if self.requires_original_birth(){return Err(ValueError::invariant("cursor Birth must settle before original close"))}if !self.requires_original_control(){return self.close_into(body,effect,reply)}let invocation=effect.invocation().ok_or_else(||ValueError::invariant("cursor original close lacks invocation"))?;if !self.state.close.is_empty(){if invocation.mode()!=crate::OriginalEffectCallbackMode::Receive{return Err(ValueError::invariant("cursor close is not its original receive invocation"))}if self.state.close_route.is_some(){return Err(ValueError::invariant("cursor has an unresolved original close invocation"))}let key=(invocation.identity(),3,body);let state=&mut *self.state;let mut scope=reply.progress().scope(&mut state.close_route,key)?;let done=state.close.step_original_into(original,body,effect,scope.borrow()?)?;drop(done);Ok(scope.forwarded())}else{if invocation.mode()!=crate::OriginalEffectCallbackMode::Receive{return Err(ValueError::invariant("cursor close is not its original receive invocation"))}if self.state.close_route.is_some(){return Err(ValueError::invariant("cursor has an unresolved original close invocation"))}let key=(invocation.identity(),4,body);let state=&mut *self.state;let mut scope=reply.progress().scope(&mut state.close_route,key)?;let done=RetainedCloneBinding::close_original_into(&mut state.source,original,body,effect,scope.borrow()?)?;drop(done);Ok(scope.forwarded())}}
 fn recover_close_original_into<'reply>(&mut self,original:&mut crate::OriginalRetirementCloseLoan<'_>,body:usize,effect:&mut crate::RetainedAllocationEffect<'_>,reply:crate::retained_clone::OriginalEffectReply<'reply,RetainedCloneStep,crate::OriginalRetirementFailure>)->Result<crate::retained_clone::OriginalEffectReplyComplete<'reply,RetainedCloneStep,crate::OriginalRetirementFailure>,ValueError>{let (identity,route,selected_body)=self.state.close_route.ok_or_else(||ValueError::invariant("cursor has no original close invocation"))?;if selected_body!=body||!effect.invocation().is_some_and(|i|i.identity()==identity&&i.mode()==crate::OriginalEffectCallbackMode::Recover){return Err(ValueError::invariant("cursor original close recovery changed invocation"))}if route==1||route==2{return self.recover_close_into(body,effect,reply)}let state=&mut *self.state;let mut scope=reply.progress().scope(&mut state.close_route,(identity,route,selected_body))?;let child=scope.borrow()?;let done=match route{3=>state.close.recover_step_original_into(original,body,effect,child),4=>RetainedCloneBinding::recover_close_original_into(&mut state.source,original,body,effect,child),_=>Err(ValueError::invariant("cursor close route changed"))}?;drop(done);Ok(scope.forwarded())}
    fn begin_close_demand(&self)->Result<crate::RetirementDemand,crate::ValueError>{Ok(crate::retained_clone::retained_close_start_demand(self.state.closing))}
fn begin_close_work_demand(&self)->Result<u64,crate::ValueError>{Ok(crate::retained_clone::retained_close_start_work_demand(self.state.closing))}
fn begin_close_paid(&mut self,effect:&mut crate::RetainedAllocationEffect<'_>)->crate::RetainedWorkOutcome<crate::retained_clone::RetainedCloneProgress>{crate::retained_clone::start_retained_close(&mut self.state.closing,effect)}
fn begin_close_into<'reply>(&mut self,effect:&mut crate::RetainedAllocationEffect<'_>,reply:crate::retained_clone::OriginalEffectReply<'reply,RetainedCloneStep,crate::OriginalRetirementFailure>)->Result<crate::retained_clone::OriginalEffectReplyComplete<'reply,RetainedCloneStep,crate::OriginalRetirementFailure>,ValueError>{let turn=self.begin_close_paid(effect);Ok(reply.complete(turn.result.map(RetainedCloneStep::Progress).map_err(Into::into)))}
fn output_ready(&self)->bool{!self.state.closing&&!self.state.spent&&self.state.admitted&&self.state.output.is_some()}
 fn advance_demands(&self,source:RetainedCloneRef<'_,SealedShared<T>>,_body:usize,maximum_work_units:u64)->Result<RetirementDemand,ValueError>{if self.state.closing||self.state.spent||self.state.output.is_some()&&!self.state.admitted{return Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"original shared clone is closing or spent"));}if let Some(demand)=source.binding_demand(&self.state.source)?{return Ok(demand);}Ok(RetirementDemand{copy_bytes:SealedShared::<T>::duplicate_copy_bytes(),depth:1,..Default::default()})}
 fn advance_work_demand(&self,source:RetainedCloneRef<'_,SealedShared<T>>,body:usize,maximum_work_units:u64)->Result<u64,ValueError>{let selected=(||->Result<u64,crate::ValueError>{self.advance_demands(source,body,maximum_work_units)?;Ok(if maximum_work_units==0||self.output_ready(){0}else if self.state.source.is_none(){source.binding_work_demand(&self.state.source)?}else{source.get().duplicate_work_demand()?})})();selected.map(|work|if work<=maximum_work_units{work}else{0})}
 fn take_work_demand(&self)->Result<u64,ValueError>{Ok(u64::from(self.output_ready()))}
 fn close_work_demand(&self,body:usize)->Result<u64,ValueError>{if self.state.close_route.is_some_and(|(_,_,selected)|selected!=body){return Err(ValueError::invariant("shared clone close body changed"))}if !self.state.closing||self.terminal_is_empty(){return Ok(0)}self.state.close.next_owner_work::<SealedShared<T>>(self.state.output.is_some(),&self.state.source,body)}
 fn advance_into<'reply>(&mut self,source:RetainedCloneRef<'_,SealedShared<T>>,body:usize,maximum:u64,effect:&mut crate::RetainedAllocationEffect<'_>,reply:crate::retained_clone::OriginalEffectReply<'reply,RetainedCloneStep,crate::OriginalRetirementFailure>)->Result<crate::retained_clone::OriginalEffectReplyComplete<'reply,RetainedCloneStep,crate::OriginalRetirementFailure>,ValueError>{if self.output_ready(){source.binding_demand(&self.state.source)?;return Ok(reply.complete(Ok(RetainedCloneStep::Complete(Default::default()))))}let maximum=maximum.min(effect.remaining_work_units()?);let demand=self.advance_demands(source,body,maximum)?;let work=self.advance_work_demand(source,body,maximum)?;if work==0||work>maximum||!super::retained_clone_grant_admits(effect.grant(),demand){return Ok(reply.complete(Ok(RetainedCloneStep::Progress(Default::default()))))}if source.binding_demand(&self.state.source)?.is_some(){let turn=source.bind(&mut self.state.source,effect);return Ok(reply.complete(turn.result.map(|p|RetainedCloneStep::Progress(p.unwrap_or_default())).map_err(Into::into)))}let turn=source.get().duplicate_into(&mut self.state.output,effect);if self.state.output.is_some(){self.state.admitted=true}Ok(reply.complete(turn.result.map_err(Into::into)))}
 fn recover_advance_into<'reply>(&mut self,_source:RetainedCloneRef<'_,SealedShared<T>>,_body:usize,_maximum:u64,_effect:&mut crate::RetainedAllocationEffect<'_>,reply:crate::retained_clone::OriginalEffectReply<'reply,RetainedCloneStep,crate::OriginalRetirementFailure>)->Result<crate::retained_clone::OriginalEffectReplyComplete<'reply,RetainedCloneStep,crate::OriginalRetirementFailure>,ValueError>{Ok(reply.pending())}
 fn take_demand(&self)->Result<RetirementDemand,ValueError>{crate::retained_clone::retained_clone_cursor_take_demand::<SealedShared<T>,bool>()}
    fn take<'reply>(&mut self,output:&mut Option<SealedShared<T>>,effect:&mut crate::RetainedAllocationEffect<'_>,reply:crate::retained_clone::OriginalEffectReply<'reply,RetainedCloneStep,ValueError>)->Result<crate::retained_clone::OriginalEffectReplyComplete<'reply,RetainedCloneStep,ValueError>,ValueError>{crate::retained_clone::take_retained_clone_cursor_output!(self.output_ready(),self.state.output,output,self.state.spent,true,effect,reply,SealedShared<T>,bool)}
 
 fn terminal_is_empty(&self)->bool{self.state.closing&&self.state.close_route.is_none()&&self.state.output.is_none()&&self.state.source.is_none()&&self.state.close.is_empty()}
 fn next_close_copy_byte_demand(&self)->Result<usize,ValueError>{self.state.close.next_copy_with_binding(&self.state.source)}
 fn next_close_capacity_byte_demand(&self,body:usize)->Result<usize,ValueError>{self.state.close.next_owner_capacity_with_binding::<SealedShared<T>>(self.state.output.is_some(),body,&self.state.source)}
 fn next_close_release_byte_demand(&self)->Result<usize,ValueError>{self.state.close.next_release_with_binding(&self.state.source)}
 fn next_close_depth_demand(&self)->Result<usize,ValueError>{self.state.close.next_owner_depth_with_binding(self.state.output.is_some(),&self.state.source)}
  fn close_started(&self)->bool{self.state.closing}
 fn close_demands(&self,body:usize)->Result<RetirementDemand,ValueError>{if self.state.close_route.is_some_and(|(_,_,selected)|selected!=body){return Err(ValueError::invariant("shared clone close body changed"))}if !self.state.closing{return Ok(Default::default());}self.state.close.next_owner_demands::<SealedShared<T>>(self.state.output.is_some(),&self.state.source,body)}

}
impl<T:Send+Sync+'static> Drop for SharedCloneCursor<T>{fn drop(&mut self){if self.state.close_route.is_none()&&self.state.output.is_none()&&self.state.source.is_none()&&self.state.close.is_empty(){unsafe{ManuallyDrop::drop(&mut self.state)}}else if !std::thread::panicking(){panic!("original shared clone retains unpublished output or source binding")}}}

#[doc(hidden)]
pub struct SharedCloneRetirement<T:Send+Sync+'static>{cursor:ManuallyDrop<SharedCloneCursor<T>>,reply:ManuallyDrop<Option<Result<RetainedCloneStep,crate::OriginalRetirementFailure>>>,action:Option<(crate::OriginalEffectInvocationIdentity,u8,usize)>}
impl<T:Send+Sync+'static> SharedCloneRetirement<T>{
 fn relay<'reply>(&mut self,mut original:Option<&mut crate::OriginalRetirementCloseLoan<'_>>,body:usize,effect:&mut crate::RetainedAllocationEffect<'_>,reply:crate::retained_clone::OriginalEffectReply<'reply,RetirementStep,crate::OriginalRetirementFailure>,recover:bool)->Result<crate::retained_clone::OriginalEffectReplyComplete<'reply,RetirementStep,crate::OriginalRetirementFailure>,ValueError>{
  let invocation=effect.invocation().ok_or_else(||ValueError::invariant("shared retirement lacks original invocation"))?;let identity=invocation.identity();let mode=invocation.mode();if recover{if !self.action.is_some_and(|(id,_,selected)|id==identity&&selected==body)||mode!=crate::OriginalEffectCallbackMode::Recover{return Err(ValueError::invariant("shared retirement recovery changed invocation"))}}else{if self.action.is_some()||mode!=crate::OriginalEffectCallbackMode::Receive{return Err(ValueError::invariant("shared retirement has unresolved invocation"))}let route=if !self.cursor.close_started(){1}else if original.is_some(){3}else{2};self.action=Some((identity,route,body))}
  let before=effect.performed_work();if self.reply.is_none(){let child=crate::retained_clone::OriginalEffectReply::borrow(&mut self.reply)?;let route=self.action.ok_or_else(||ValueError::invariant("shared retirement lost route"))?.1;let done=match(recover,route){(false,1)=>self.cursor.begin_close_into(effect,child),(true,1)=>self.cursor.recover_begin_close_into(effect,child),(false,2)=>self.cursor.close_into(body,effect,child),(true,2)=>self.cursor.recover_close_into(body,effect,child),(false,3)=>self.cursor.close_original_into(original.as_deref_mut().ok_or_else(||ValueError::invariant("shared retirement lost original control"))?,body,effect,child),(true,3)=>self.cursor.recover_close_original_into(original.as_deref_mut().ok_or_else(||ValueError::invariant("shared retirement lost original control"))?,body,effect,child),_=>Err(ValueError::invariant("shared retirement route changed"))}?;drop(done)}
  match self.reply.take(){None=>Ok(reply.pending()),Some(result)=>{self.action=None;let work=effect.performed_work().checked_sub(before).ok_or_else(||ValueError::invariant("shared retirement work moved backwards"))?;Ok(reply.complete(result.map(|step|RetirementStep::Progress(step.progress(),work))))}}
 }
}
impl<T:Send+Sync+'static> RetirementCursor for SharedCloneRetirement<T>{
 fn close_into<'reply>(&mut self,body:usize,effect:&mut crate::RetainedAllocationEffect<'_>,reply:crate::retained_clone::OriginalEffectReply<'reply,RetirementStep,crate::OriginalRetirementFailure>)->Result<crate::retained_clone::OriginalEffectReplyComplete<'reply,RetirementStep,crate::OriginalRetirementFailure>,ValueError>{self.relay(None,body,effect,reply,false)}
 fn recover_close_into<'reply>(&mut self,body:usize,effect:&mut crate::RetainedAllocationEffect<'_>,reply:crate::retained_clone::OriginalEffectReply<'reply,RetirementStep,crate::OriginalRetirementFailure>)->Result<crate::retained_clone::OriginalEffectReplyComplete<'reply,RetirementStep,crate::OriginalRetirementFailure>,ValueError>{self.relay(None,body,effect,reply,true)}
 fn close_original_into<'reply>(&mut self,original:&mut crate::OriginalRetirementCloseLoan<'_>,body:usize,effect:&mut crate::RetainedAllocationEffect<'_>,reply:crate::retained_clone::OriginalEffectReply<'reply,RetirementStep,crate::OriginalRetirementFailure>)->Result<crate::retained_clone::OriginalEffectReplyComplete<'reply,RetirementStep,crate::OriginalRetirementFailure>,ValueError>{self.relay(Some(original),body,effect,reply,false)}
 fn recover_close_original_into<'reply>(&mut self,original:&mut crate::OriginalRetirementCloseLoan<'_>,body:usize,effect:&mut crate::RetainedAllocationEffect<'_>,reply:crate::retained_clone::OriginalEffectReply<'reply,RetirementStep,crate::OriginalRetirementFailure>)->Result<crate::retained_clone::OriginalEffectReplyComplete<'reply,RetirementStep,crate::OriginalRetirementFailure>,ValueError>{self.relay(Some(original),body,effect,reply,true)}
 fn requires_original_birth(&self)->bool{self.cursor.close_started()&&self.cursor.requires_original_birth()}
 fn close_original_birth_step(&mut self,original:&mut crate::OriginalRetirementCloseLoan<'_>,grant:RetainedCloneGrant)->RetirementStep{match self.cursor.close_original_birth_step(original,grant){crate::RetainedWorkPoll::Pending{work}=>RetirementStep::Pending(work),crate::RetainedWorkPoll::Complete(turn)=>match turn.result{Ok(step)=>RetirementStep::Progress(step.progress(),turn.work),Err(error)=>RetirementStep::Failure(error,turn.work)}}}
 fn requires_original_control(&self)->bool{self.cursor.close_started()&&self.cursor.requires_original_control()}

  fn next_demand(&self,body:usize)->Result<RetirementDemand,ValueError>{if self.action.is_some_and(|(_,_,selected)|selected!=body){return Err(ValueError::invariant("shared retirement body changed"))}if self.cursor.close_started(){self.cursor.close_demands(body)}else{self.cursor.begin_close_demand()}}
fn next_computational_work(&self,body:usize)->Result<u64,ValueError>{if self.action.is_some_and(|(_,_,selected)|selected!=body){return Err(ValueError::invariant("shared retirement body changed"))}if self.cursor.close_started(){self.cursor.close_work_demand(body)}else{self.cursor.begin_close_work_demand()}}
 fn terminal_is_empty(&self)->bool{self.action.is_none()&&self.reply.is_none()&&self.cursor.terminal_is_empty()}
 fn next_work_byte_demand(&self)->Result<usize,ValueError>{self.cursor.next_close_copy_byte_demand()}
 fn next_birth_bytes(&self,body:usize)->Option<usize>{self.cursor.next_close_capacity_byte_demand(body).ok()}
 fn next_close_byte_demand(&self)->Option<usize>{self.cursor.next_close_release_byte_demand().ok()}
 fn next_depth_demand(&self)->Result<usize,ValueError>{self.cursor.next_close_depth_demand()}
 fn allows_admitted_narrow_work(&self)->bool{true}
 fn terminal_release_bytes(&self)->Option<usize>{self.terminal_is_empty().then_some(size_of::<Self>())}
}
impl<T:Send+Sync+'static> Drop for SharedCloneRetirement<T>{fn drop(&mut self){if self.action.is_none()&&self.reply.is_none()&&self.cursor.terminal_is_empty(){unsafe{ManuallyDrop::drop(&mut self.cursor);ManuallyDrop::drop(&mut self.reply)}}else if !std::thread::panicking(){panic!("original shared clone retirement frame remains retained")}}}
impl<T:Send+Sync+'static> RetireOwned for SharedCloneCursor<T>{
 type RetirementCursor=SharedCloneRetirement<T>;
 fn retirement_seed(self)->Self::RetirementCursor{SharedCloneRetirement{cursor:ManuallyDrop::new(self),reply:ManuallyDrop::new(None),action:None}}
 fn retirement_birth_bytes(&self)->Option<usize>{Some(size_of::<SharedCloneRetirement<T>>())}
 fn controlled_retirement_supported()->bool{true}
}
